// Get the XML-to-JSON result
const input = $input.first().json;

// Depending on the XML structure, channel may be directly available
// or nested under rss.
const channel = input.channel ?? input.rss?.channel;

if (!channel) {
  throw new Error('RSS channel not found in the XML output.');
}

// Normalize item into an array
const rawItems = channel.item ?? [];
const articles = Array.isArray(rawItems) ? rawItems : [rawItems];

// Convert each article into a clean n8n item
return articles
  .filter(article => article && article.title)
  .map(article => ({
    json: {
      title: article.title,
      link: article.link ?? '',
      description: article.description ?? '',
      pubDate: article.pubDate ?? '',
      category: article.category ?? '',
      image: article['media:content']?.url ?? ''
    }
  }));

const topics = [
  "Why API contracts matter in full-stack applications",
  "Why database design matters before writing application code",
  "Why authentication and authorization are different",
  "Why error handling matters in production applications",
  "Why clean UI does not automatically mean good UX",
  "Why software should be designed around real user workflows",
  "Why logging is important when debugging backend applications",
  "Why input validation should happen on the backend",
  "Why small automation can save repetitive developer work",
  "Why building features is easier than building reliable software"
];

return topics.map(topic => ({
  json: {
    topic
  }
}));

const topics = [
  {
    topic: "Why I chose n8n instead of building the entire automation logic from scratch",
    angle: "Tool choice"
  },
  {
    topic: "What makes an automation workflow reliable instead of just functional",
    angle: "Reliability"
  },
  {
    topic: "Why duplicate prevention matters in automated content systems",
    angle: "Data integrity"
  },
  {
    topic: "Designing fallback behavior when an automation has no data to work with",
    angle: "Error handling"
  },
  {
    topic: "Why I am testing the automation locally before deploying it to the cloud",
    angle: "Development strategy"
  },
  {
    topic: "What I learned from connecting multiple branches in an n8n workflow",
    angle: "Workflow design"
  },
  {
    topic: "Why automation should fail safely instead of generating something incorrect",
    angle: "AI safety"
  },
  {
    topic: "Using Google Sheets as a simple data layer for an automation project",
    angle: "Data management"
  },
  {
    topic: "What changes when an automation needs to run 24/7",
    angle: "Cloud architecture"
  },
  {
    topic: "Why API rate limits become important when building AI automations",
    angle: "API engineering"
  },
  {
    topic: "How I am thinking about separating content generation from content history",
    angle: "System design"
  },
  {
    topic: "Why testing edge cases matters more than testing only the happy path",
    angle: "Testing"
  },
  {
    topic: "The difference between an AI generator and an actual content agent",
    angle: "AI agents"
  },
  {
    topic: "How scheduling changes the design of an automation workflow",
    angle: "Scheduling"
  },
  {
    topic: "Why human approval can still be useful in an automated publishing workflow",
    angle: "Human-in-the-loop"
  },
  {
    topic: "What I am considering before connecting the workflow to LinkedIn",
    angle: "Production planning"
  },
  {
    topic: "How small automation decisions can create unexpected workflow problems",
    angle: "Debugging"
  },
  {
    topic: "What I want this automation to handle automatically before I call it production-ready",
    angle: "Production readiness"
  }
];

return topics.map(item => ({
  json: {
    topic: item.topic,
    angle: item.angle
  }
}));

const items = $input.all();

return items.map(item => {
  const post = String(item.json.text ?? '').trim();

  const issues = [];

  // 1. Post must exist
  if (!post) {
    issues.push('Post is empty');
  }

  // 2. Reasonable LinkedIn length
  if (post.length < 100) {
    issues.push('Post is too short');
  }

  if (post.length > 3000) {
    issues.push('Post is too long');
  }

  // 3. Must contain hashtags
  const hashtagCount = (post.match(/#[A-Za-z0-9_]+/g) || []).length;

  if (hashtagCount < 3) {
    issues.push('Fewer than 3 hashtags');
  }

  if (hashtagCount > 5) {
    issues.push('More than 5 hashtags');
  }

  // 4. Detect common placeholder/generation text
  const suspiciousPhrases = [
    'output from',
    'generated post',
    'your linkedin post',
    'placeholder',
    'undefined',
    'null',
    '[insert',
    '[add ',
    'as an ai'
  ];

  const lowerPost = post.toLowerCase();

  for (const phrase of suspiciousPhrases) {
    if (lowerPost.includes(phrase)) {
      issues.push(`Suspicious text: "${phrase}"`);
    }
  }

  return {
    json: {
      ...item.json,
      qualityPassed: issues.length === 0,
      qualityIssues: issues.join('; '),
      postLength: post.length,
      hashtagCount
    }
  };
});

